398 │     fn to_inline_range(&self, range: Range<usize>) -> InlineRange {
399 │         let mut start = 0;
400 │         let mut start_char = 0;
401 │         let mut end = 0;
402 │         let mut end_char = 0;
403 │ 
404 │         for (line, &line_start) in self.line_starts.iter().enumerate() {
405 │             if line_start <= range.start {
406 │                 start = line;
407 │                 start_char = range.start - line_start;
408 │             }
409 │             if line_start <= range.end {
410 │                 end = line;
411 │                 end_char = range.end - line_start;
412 │             }
413 │         }
414 │ 
415 │         Position {
416 │             line: start,
417 │             character: start_char,
418 │         }..Position {
419 │             line: end,
420 │             character: end_char,
421 │         }
422 │     }
