427 │ 
428 │         for (line, &line_start) in self.line_starts.iter().enumerate() {
429 │             if line_start <= range.start {
430 │                 start = line;
431 │             }
432 │             if line_start <= range.end {
433 │                 end = line;
434 │             }
435 │         }
436 │ 
437 │         if start == end {
438 │             end += 1;
439 │         }
440 │ 
441 │         start..end
442 │     }
443 │ }
